begin;
create function pg_temp.assert_true(p boolean,label text) returns void language plpgsql as $$ begin if p is distinct from true then raise exception 'FAILED: %',label; end if; end; $$;
grant execute on function pg_temp.assert_true(boolean,text) to authenticated,anon,service_role;
insert into auth.users(id,email,email_confirmed_at) values('00000000-0000-4000-a000-000000000080','post-owner@example.invalid',now()),('00000000-0000-4000-a000-000000000081','post-student@example.invalid',now());
insert into auth.sessions(id,user_id) values('00000000-0000-4000-b000-000000000080','00000000-0000-4000-a000-000000000080'),('00000000-0000-4000-b000-000000000081','00000000-0000-4000-a000-000000000081');
insert into private.app_owners(user_id) values('00000000-0000-4000-a000-000000000080');
insert into public.instagram_feed_posts(id,source_username,post_url,caption,posted_at,moderation_status) values('post_review_test','rarenightclub','https://www.instagram.com/p/post_review_test/','Synthetic review fixture',now(),'approved'),('post_review_bad_url','rarenightclub','https://evil.invalid/post/','Synthetic invalid URL',now(),'approved');
select pg_temp.assert_true((select moderation_status='pending' and moderation_revision=1 from public.instagram_feed_posts where id='post_review_test'),'new imports cannot publish themselves');
set local role anon;
select pg_temp.assert_true((select count(*)=0 from public.instagram_feed_posts where id like 'post_review_%'),'guest cannot read pending posts');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-a000-000000000081","role":"authenticated","session_id":"00000000-0000-4000-b000-000000000081"}',true);
set local role authenticated;
do $$ begin begin perform public.owner_portal('posts','{}'); raise exception 'Expected owner denial'; exception when insufficient_privilege then null; end; end $$;
do $$ begin begin perform private.review_post('post_review_test','approved'); raise exception 'Expected private denial'; exception when insufficient_privilege then null; end; end $$;
do $$ begin begin update public.instagram_feed_posts set moderation_status='approved' where id='post_review_test'; raise exception 'Expected write denial'; exception when insufficient_privilege then null; end; end $$;
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-a000-000000000080","role":"authenticated","session_id":"00000000-0000-4000-b000-000000000080"}',true);
set local role authenticated;
select pg_temp.assert_true(exists(select 1 from jsonb_array_elements(public.owner_portal('posts','{"status":"pending"}')) p where p->>'id'='post_review_test'),'owner can read private queue');
do $$ begin begin perform public.owner_portal('review_post','{"id":"post_review_test","decision":"approved","expected_revision":1,"expected_status":"pending","extra":true}'); raise exception 'Expected payload denial'; exception when sqlstate '22023' then null; end; end $$;
do $$ begin begin perform public.owner_portal('review_post','{"id":"post_review_bad_url","decision":"approved","expected_revision":1,"expected_status":"pending"}'); raise exception 'Expected source denial'; exception when raise_exception then if sqlerrm='Expected source denial' then raise; end if; end; end $$;
select public.owner_portal('review_post','{"id":"post_review_test","decision":"approved","expected_revision":1,"expected_status":"pending"}');
reset role;
select pg_temp.assert_true((select moderation_status='approved' and moderation_revision=2 from public.instagram_feed_posts where id='post_review_test'),'approval publishes inspected revision');
select pg_temp.assert_true((select count(*)=1 from private.owner_review_log where post_id='post_review_test' and action='post_approved'),'review is recorded');
set local role anon;
select pg_temp.assert_true((select count(*)=1 from public.instagram_feed_posts where id='post_review_test'),'guest sees approved post');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
insert into public.instagram_feed_posts(id,source_username,post_url,caption,posted_at,moderation_status) select id,source_username,post_url,caption,posted_at,'approved' from public.instagram_feed_posts where id='post_review_test' on conflict(id) do update set caption=excluded.caption,moderation_status=excluded.moderation_status;
reset role;
select pg_temp.assert_true((select moderation_status='approved' and moderation_revision=2 from public.instagram_feed_posts where id='post_review_test'),'unchanged sync preserves review');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
update public.instagram_feed_posts set caption='Synthetic edited caption',moderation_status='approved' where id='post_review_test';
reset role;
select pg_temp.assert_true((select moderation_status='pending' and moderation_revision=3 from public.instagram_feed_posts where id='post_review_test'),'edits require another review');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-a000-000000000080","role":"authenticated","session_id":"00000000-0000-4000-b000-000000000080"}',true);
set local role authenticated;
do $$ begin begin perform public.owner_portal('review_post','{"id":"post_review_test","decision":"approved","expected_revision":2,"expected_status":"approved"}'); raise exception 'Expected stale denial'; exception when raise_exception then if sqlerrm='Expected stale denial' then raise; end if; end; end $$;
select public.owner_portal('review_post','{"id":"post_review_test","decision":"rejected","expected_revision":3,"expected_status":"pending"}');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
update public.instagram_feed_posts set caption='Synthetic changed rejected post',moderation_status='approved' where id='post_review_test';
reset role;
select pg_temp.assert_true((select moderation_status='rejected' from public.instagram_feed_posts where id='post_review_test'),'sync cannot restore rejected content');
rollback;
